    if not grid: 
        return 0 

    row = len(grid) 
    col = len(grid[0]) 

    num_islands = 0

    for i in range(row): 
        for j in range(col): 
            if grid[i][j] == 1: 
                num_islands += dfs(grid, i, j, row, col) 

