class Neural_Network:
    def __init__(self, learning_rate=0.01):
        self.learning_rate = learning_rate

    def sgd(self, values, target):
        guess = sum(values)*self.learning_rate

        gradients = [(2 * (guess - target)) for value in values]

        for gradient_index in range(len(gradients)):
            values[gradient_index] -= gradients[gradient_index] * self.learning_rate
        return values

def findLongestIncreasingSubsequence(sequence): 
    n = len(sequence) 

    # LIS[i] stores the length of the longest increasing 
    # subsequence upto index i 
    # Initialize the sequence as 1
    LIS = [1 for i in range(n)] 

    # Compute LIS values for all indexes  
    for i in range (1 , n): 
        for j in range(0 , i): 
            if sequence[i] > sequence[j] and LIS[i]< LIS[j] + 1 : 
                LIS[i] = LIS[j]+1

    # Return  the maximum value 
    return max(LIS)

