    # Function to remove a node from linked list
    def remove(self, value): 
        temp = self.head

        # If head node itself holds the key 
        # or multiple occurrences of key
        while temp is not None:
            if temp.data == value:
                break
            prev = temp
            temp = temp.next
        if temp == None:
            return 
        if temp == self.head: 
            self.head = temp.next 
        else: 
            prev.next = temp.next

