    for item in data:
        if item not in counted_data:
            counted_data[item] = 1
        else:
            counted_data[item] += 1
    highest_count = 0
    modes = []
    for key, value in counted_data.items():
        if value > highest_count:
            modes = [key]
            highest_count = value
        elif value == highest_count:
            modes.append(key)
    if len(modes) == len(data):
        modes = []
    return modes

