    for i in range(m + 1): 
        C[i][0] = 0

    # palindromic substring of length 1 
    for j in range(n + 1): 
        C[0][j] = 0

    # fill the matrix in bottom-up manner 
    for i in range(1, m + 1): 
        for j in range(1, n + 1): 
            if string1[i - 1] == string2[j - 1]: 
                C[i][j] = C[i - 1][j - 1] + 1
    return m == n == C[m][n]

