def get_anagrams(string):
    anagrams = []
    for i in range(len(string)):
        for j in range(len(string)):
            if i == j:
                continue
            s1 = string[i:j+1]
            s2 = string[:i] + string[j+1:]
            if is_anagram(s1, s2):
                anagrams.append(s2)
    return anagrams

def permute(nums):
    if len(nums) <= 1:
        return [nums]

    permutations = []
    for i in range(len(nums)):
        v = nums[i]
        left = nums[:i] + nums[i+1:]
        subpermute = permute(left)
        for item in subpermute:
            permutations.append([v] + item)
    return permutations

def descending_order(nums):
