 return 0

 if maxWeight == 0:
 return 0

 if len(weights) == 1:
 if weights[0] <= maxWeight:
 return values[0]
 else:
 return 0

 if weights[0] > maxWeight:
 return knapsack(weights[1:], values[1:], maxWeight)

