def num_routes(grid_dim, start, end):
    paths = 1
    xdiff = end[0] - start[0]
    ydiff = end[1] - start[1]
    num_rows, num_cols = grid_dim
    max_x = num_rows - 1 - xdiff
    max_y = num_cols - 1 - ydiff
    for x in range(0, max_x):
        paths *= (x+ydiff+1)
    for y in range(0, max_y):
        paths *= (y+xdiff+1)
    return int(paths/math.factorial(xdiff+ydiff))

