def eval(node):
    if node.isLeaf():
        return node.value

    left = eval(node.left)
    right = eval(node.right)

    if node.op == '+':
        return left + right
    if node.op == '-':
        return left - right
    if node.op == '*':
        return left * right
    if node.op == '/':
        return left / right

