def left_rotate_array(arr, d):
    n = len(arr)
    if d % n == 0: 
        return
    for _ in range(d):
        i = 0
        temp = arr[0]
        for i in range(n - 1):
            arr[i] = arr[i + 1]
        arr[n - 1] = temp

